pub(super) const BRT_IMAGE_EVIDENCE: &str = "Original US BRTD/U247/457/467/478 entry-7 image and palette-zero fields. Exact archive, slot 513..520, physical LBA, entry geometry, mode, destination, checkword and payload identities. Conditional GAME family-1/2 publisher roots are copied from actor 0 to saved record 0 by original BATTLE entry-15 0x800A7C14, entered through JAL 0x800A69D4. Original 0x801E12DC queues mode 0/selector 12 and publishes the actor pointer; 0x801E5824/0x801E5AF4/0x801E7818 dispatch request 0x801E7948 and post-load 0x801E7BA0. Stable plain hint 7/13/14/15, flag 0x8000, saved active/status bits, finite byte-8 selectors, count one, actor index zero, valid nonaliased work and stats, unskipped successful loading, retained saved root/byte24 and ordinary noninterfering helpers are conditions. The post-load full-record copy restores the root and preserves request byte 8; JALs 0x801E8414/0x801E8438 reach SLUS image selection and palette index zero. Complete checked decompression requires every literal alias in the reviewed image-directory/header/encoding or palette relative-word/32-halfword union. Root-array words, unselected images, program/cell/selection fields, opaque prefixes and tails excluded. No natural state production, actual invocation, residency, upload, display, rasterized-text absence or safe-edit claim.";

