pub(super) fn model_palette_zero_fields(decoded: &[u8], typed: &[u8]) -> Vec<(usize, usize)> {
    let word = |at: usize| {
        decoded
            .get(at..at.checked_add(4)?)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()) as usize)
    };
    let [Some(first), Some(second), Some(third)] = [word(0), word(4), word(8)] else {
        return Vec::new();
    };
    if first != 12 || first >= second || second >= third || third >= decoded.len() {
        return Vec::new();
    }
    let roots = [first, second, third];
    let reviewed = |at: usize| {
        typed
            .get(at..at + 4)
            .is_some_and(|roles| roles.iter().all(|role| role & 3 != 0))
    };
    let mut fields = Vec::new();
    for (index, &root) in roots.iter().enumerate() {
        let end = roots.get(index + 1).copied().unwrap_or(decoded.len());
        if root + 16 > end || !reviewed(index * 4) || !reviewed(root) {
            continue;
        }
        let Some((palette_relative, program_relative)) = word(root + 4).zip(word(root + 8)) else {
            continue;
        };
        let Some(table) = root.checked_add(palette_relative) else {
            continue;
        };
        let Some(program) = root.checked_add(program_relative) else {
            continue;
        };
        if !(root + 16..program).contains(&table) || program >= end || table + 4 > program {
            continue;
        }
        let Some(relative) = word(table) else {
            continue;
        };
        let Some(record) = table.checked_add(relative) else {
            continue;
        };
        if relative < 4
            || relative % 4 != 0
            || record.checked_add(64).is_none_or(|end| end > program)
        {
            continue;
        }
        fields.extend([
            (root + 4, root + 8),
            (table, table + 4),
            (record, record + 64),
        ]);
    }
    fields
}

pub(super) fn compression_metadata_ranges(
    entry: Entry,
    data: &[u8],
    literal_profile: (&[(usize, usize)], &'static str),
    additional_literal_profile: (&[(usize, usize)], &'static str),
    program_literal_profile: (&[(usize, usize)], &'static str),
) -> Option<Vec<NontextRange>> {
    let (literal_fields, literal_evidence) = literal_profile;
    let (additional_fields, additional_evidence) = additional_literal_profile;
    let (program_fields, program_evidence) = program_literal_profile;
    let copy_profiles = [
        compressed_image_copy_fields(entry, data),
        compressed_sprite_copy_fields(entry, data),
        compressed_program_copy_fields(entry, data),
    ];
    let check_word = entry.check_word;
    let header = data.get(..6)?;
    if check_word == 0 || u32::from_le_bytes(header[..4].try_into().unwrap()) != check_word {
        return None;
    }
    let expected = usize::try_from(check_word).ok()?;
    let evidence = "original US type-1 EMI compression checkword, token controls, reference displacements, length extensions and terminator; original dispatch 0x80162420..0x80162444, checkword consumer 0x801623A8..0x80162420 and decoder 0x80164028..0x801644CC; exact archive identity and checked complete token walk; literal data and skipped prefix bytes excluded; no decoded-role, rasterized-text absence or runtime claim";
    let mut ranges = vec![NontextRange {
        offset: 0,
        length: 4,
        evidence,
    }];
    let selected_profile = bpl_selected_sprite_profile(entry, data);
    let brt_profile = brt_decoded_nontext_fields(entry, data);
    let track_literals = selected_profile.is_some()
        || brt_profile.is_some()
        || !literal_fields.is_empty()
        || !additional_fields.is_empty()
        || !program_fields.is_empty()
        || copy_profiles.iter().any(|(fields, _)| !fields.is_empty());
    let mut typed = vec![0_u8; if track_literals { expected } else { 0 }];
    // Each bit identifies a reviewed field union. Intersect all decoded aliases
    // before qualifying a physical literal, preserving earlier evidence first.
    for &(start, end) in literal_fields {
        typed.get_mut(start..end)?.fill(127);
    }
    for &(start, end) in additional_fields {
        for role in typed.get_mut(start..end)? {
            *role |= 126;
        }
    }
    for &(start, end) in program_fields {
        for role in typed.get_mut(start..end)? {
            *role |= 124;
        }
    }
    let mut origins = Vec::new();
    let mut decoded_bytes = Vec::new();
    let mut at = 6;
    let mut decoded = 0_usize;
    loop {
        let start = at;
        let control = *data.get(at)?;
        at += 1;
        let terminal = control == 0xff;
        let literal = control & 0x10 != 0;
        let mut count = 0;
        let mut distance = 0;
        if !terminal {
            if !literal {
                let low = usize::from(*data.get(at)?);
                at += 1;
                distance = 2048 - ((usize::from(control & 0xe0) << 3) | low);
                if distance > decoded {
                    return None;
                }
            }
            count = if literal {
                32 - usize::from(control & 31)
            } else {
                usize::from(control & 15) + 3
            };
            if count == if literal { 16 } else { 18 } {
                count += usize::from(*data.get(at)?);
                at += 1;
            }
        }
        let previous = ranges.last_mut()?;
        if previous.offset + previous.length == start {
            previous.length += at - start;
        } else {
            ranges.push(NontextRange {
                offset: start,
                length: at - start,
                evidence,
            });
        }
        if terminal {
            if at != data.len() || decoded != expected {
                return None;
            }
            break;
        }
        let end = decoded.checked_add(count)?;
        if end > expected {
            return None;
        }
        if literal {
            data.get(at..at.checked_add(count)?)?;
        }
        if track_literals {
            for index in 0..count {
                let origin = if literal {
                    at + index
                } else {
                    *origins.get(origins.len().checked_sub(distance)?)?
                };
                decoded_bytes.push(*data.get(origin)?);
                origins.push(origin);
            }
        }
        if literal {
            at += count;
        }
        decoded = end;
    }
    for (start, end) in model_palette_zero_fields(&decoded_bytes, &typed) {
        for role in typed.get_mut(start..end)? {
            *role |= 120;
        }
    }
    if let Some((selector, _)) = selected_profile {
        for (start, end) in bpl_selected_sprite_fields(&decoded_bytes, selector)? {
            for role in typed.get_mut(start..end)? {
                *role |= 112;
            }
        }
        if let Some(fields) = bpl_flag_sprite_fields(&decoded_bytes, selector & 2) {
            for (start, end) in fields {
                for role in typed.get_mut(start..end)? {
                    *role |= 96;
                }
            }
        }
    }
    let expanded_sprite_evidence = if let Some(profile) = brt_profile {
        if let Some(fields) = sprite_selector_fields(&decoded_bytes, |selector| {
            (selector.wrapping_sub(4) < 2) == (profile.family == 1)
        }) {
            for (start, end) in fields {
                for role in typed.get_mut(start..end)? {
                    *role |= 96;
                }
            }
        }
        if profile.family == 1 {
            let selected = sprite_selector_fields(&decoded_bytes, |selector| {
                matches!(selector, 8 | 9 | 20 | 21 | 24 | 25 | 48 | 49)
            })?;
            for &(start, end) in profile
                .reselected_image_fields
                .iter()
                .chain(selected.iter())
            {
                for role in typed.get_mut(start..end)? {
                    *role |= 64;
                }
            }
        }
        BRT_SPRITE_EVIDENCE
    } else {
        BPL_FLAG_SPRITE_EVIDENCE
    };
    let mut literal_roles = vec![None; if track_literals { data.len() } else { 0 }];
    for (&origin, &known) in origins.iter().zip(&typed) {
        let role = literal_roles.get_mut(origin)?;
        *role = Some(role.unwrap_or(127) & known);
    }
    let mut at = 0;
    while at < literal_roles.len() {
        let role = literal_roles[at].unwrap_or(0);
        if role == 0 {
            at += 1;
            continue;
        }
        let evidence = if role & 1 != 0 {
            literal_evidence
        } else if role & 2 != 0 {
            additional_evidence
        } else if role & 4 != 0 {
            program_evidence
        } else if role & 8 != 0 {
            "original US source-bound compressed sprite palette-zero relative words and 32-halfword record; existing reviewed image-root and source bindings, GAME 0x801C1254/0x801C1308/0x801C13DC and SLUS 0x80166C48..0x80166CAC; complete checked decode and every decoded alias confined to the reviewed image/program/palette field union; previous records retain their evidence; no actual loading, active CLUT, transfer, display, rasterized-text absence or safe-edit claim"
        } else if role & 16 != 0 {
            selected_profile?.1
        } else if role & 32 != 0 {
            expanded_sprite_evidence
        } else {
            BRT_RESELECTED_SPRITE_EVIDENCE
        };
        let start = at;
        while at < literal_roles.len() && literal_roles[at] == Some(role) {
            at += 1;
        }
        ranges.push(NontextRange {
            offset: start,
            length: at - start,
            evidence,
        });
    }
    for (copy_fields, copy_evidence) in copy_profiles {
        if copy_fields.is_empty() {
            continue;
        }
        for &(start, end) in copy_fields {
            typed.get_mut(start..end)?.fill(127);
        }
        literal_roles.fill(None);
        for (&origin, &known) in origins.iter().zip(&typed) {
            let role = literal_roles.get_mut(origin)?;
            *role = Some(role.unwrap_or(1) & u8::from(known != 0));
        }
        // Keep earlier physical records and attribute mixed origins to the copy proof.
        for range in &ranges {
            literal_roles
                .get_mut(range.offset..range.offset.checked_add(range.length)?)?
                .fill(Some(0));
        }
        let mut at = 0;
        while at < literal_roles.len() {
            if literal_roles[at] != Some(1) {
                at += 1;
                continue;
            }
            let start = at;
            while at < literal_roles.len() && literal_roles[at] == Some(1) {
                at += 1;
            }
            ranges.push(NontextRange {
                offset: start,
                length: at - start,
                evidence: copy_evidence,
            });
        }
    }
    ranges.sort_by_key(|range| range.offset);
    Some(ranges)
}
